// Package id provides globally unique, immutable identifiers.
//
// Identifiers are UUID version 7 (RFC 9562), generated by github.com/google/uuid.
// Three properties matter for this system:
//
//   - They are generated locally. A device offline for days must still create
//     products, sales, and sync events without asking a server for an
//     identifier (ADR-001).
//   - They are unique across devices without coordination, so two devices
//     working offline never collide (ADR-006).
//   - They sort by creation time. Lexicographic order is time order, which
//     gives index locality in SQLite and PostgreSQL and a natural ordering hint
//     for sync batches.
//
// This package is a thin wrapper. It exists so that domain code depends on a
// project type rather than a vendor path, and so that services can take a
// Generator and be tested against deterministic identifiers. The generation
// itself is the library's job — see ADR-011.
//
// Identifiers are immutable once assigned (SPECIFICATION.md §40). Domain
// packages name their identifiers with Typed, so that a sale identifier cannot
// be passed where a product identifier is meant.
package id

import (
	"fmt"

	"github.com/google/uuid"
)

// ID is a 128-bit unique identifier.
//
// It is an alias for uuid.UUID rather than a distinct type, so that values
// interoperate directly with the library and with any driver that already
// understands UUIDs. The zero ID is Nil and is never a valid identifier.
type ID = uuid.UUID

// Nil is the zero identifier.
var Nil = uuid.Nil

// Generator produces identifiers.
//
// Services take a Generator rather than calling New directly, so that a test
// can supply a deterministic sequence. See the idtest subpackage.
type Generator interface {
	New() (ID, error)
}

// V7 generates UUID version 7 identifiers. It is the production generator and
// is safe for concurrent use.
//
// The library guarantees that identifiers produced within the same millisecond
// still increase, so creation order survives a burst of activity at the till.
type V7 struct{}

// New returns a new version 7 identifier.
func (V7) New() (ID, error) {
	generated, err := uuid.NewV7()
	if err != nil {
		return Nil, fmt.Errorf("id: generating identifier: %w", err)
	}
	return generated, nil
}

// generator is the package-level default backing New.
var generator Generator = V7{}

// New returns a new identifier.
//
// It panics if the system entropy source fails, which no caller can sensibly
// recover from: without randomness the system cannot make identifiers that are
// safe to sync. Use V7.New to handle the failure.
func New() ID {
	generated, err := generator.New()
	if err != nil {
		panic(err)
	}
	return generated
}

// Parse reads an identifier from its text form.
//
// Parsing normalises: the canonical, braced, URN, and unhyphenated spellings of
// one identifier all yield the same value. That normalisation is what makes
// identity stable across the sync boundary, so an event resent in a different
// spelling is still recognised as the event already applied (ADR-006).
func Parse(text string) (ID, error) {
	parsed, err := uuid.Parse(text)
	if err != nil {
		return Nil, fmt.Errorf("id: parsing %q: %w", text, err)
	}
	return parsed, nil
}

// MustParse is Parse for identifiers known at compile time, such as fixtures.
// It panics on invalid input.
func MustParse(text string) ID {
	parsed, err := Parse(text)
	if err != nil {
		panic(err)
	}
	return parsed
}
